<template><SilkRoadWorkspace title="Agent 方案历史"><section class="head"><div><span>AGENT HISTORY</span><h1>智能营销方案记录</h1><p>回看商品识别、目标市场分析与内容策略，并可一键转为营销项目。</p></div><el-button :loading="loading" @click="load">刷新记录</el-button></section><div v-loading="loading" class="history-grid"><article v-for="item in items" :key="item.id"><div><el-tag>{{ item.status||'已完成' }}</el-tag><time>{{ formatTime(item.updatedAt||item.createdAt) }}</time></div><h2>{{ item.productName||'未命名商品方案' }}</h2><p>{{ [item.category,item.targetMarket,item.targetPlatform].filter(Boolean).join(' · ')||'等待补充方案信息' }}</p><footer><el-button link type="primary" @click="openResult(item)">查看结果</el-button><el-button :loading="creatingId===item.id" @click="createProject(item)">创建营销项目</el-button></footer></article></div><el-empty v-if="!loading&&!items.length" description="暂无 Agent 营销方案记录"><el-button type="primary" @click="router.push('/agent')">运行丝路 Agent</el-button></el-empty></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{agentAPI,type AgentHistoryItem}from'@/api/agent';const router=useRouter(),items=ref<AgentHistoryItem[]>([]),loading=ref(false),creatingId=ref<number>();const formatTime=(v:string)=>v?new Date(v).toLocaleString():'-';const load=async()=>{loading.value=true;try{items.value=(await agentAPI.listHistory({limit:50})).items||[]}finally{loading.value=false}};const openResult=(item:AgentHistoryItem)=>router.push({path:'/agent/result',query:{historyId:String(item.id)}});const createProject=async(item:AgentHistoryItem)=>{creatingId.value=item.id;try{const created=await agentAPI.createProjectFromAgent(item.id);ElMessage.success('已创建营销项目');router.push(`/projects/${created.project_id}`)}catch(e:any){ElMessage.error(e?.message||'创建项目失败')}finally{creatingId.value=undefined}};onMounted(load)</script>
<style scoped>.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:24px}.head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.head h1{font-size:30px;margin:8px 0}.head p{color:var(--text-secondary)}.history-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:18px;min-height:120px}.history-grid article{padding:21px;border:1px solid var(--border-primary);border-radius:18px;background:var(--bg-card)}.history-grid article>div{display:flex;justify-content:space-between}.history-grid time{font-size:12px;color:var(--text-muted)}.history-grid h2{font-size:19px;margin:17px 0 9px}.history-grid p{color:var(--text-secondary)}.history-grid footer{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}</style>
